'use strict';
(function(){
 const $=s=>document.querySelector(s);
 const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(!$('#respond-context')){window.location.replace('respond-integration.html?release=six-areas-1');return}
 const gbp=x=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:2}).format(x);
 const pct=(a,b)=>b?(a/b*100).toFixed(1)+'%':'N/A — no sampled QA';
 const names=['Source case','Governed transfer','Field mapping','Validation gate','Analytics & lineage','Human review'];
 let fullData,scope='all',pool=[],data,step=0,selected=0,mode='extract',includeExceptions=true,result=null,ack=false,runCount=0;
 const source=()=>RespondDemo.sourceRecord(pool[selected]);
 const batch=()=>RespondDemo.fixture(pool,includeExceptions);
 const chosen=()=>pool[selected];
 const field=(label,value)=>`<div><small>${label}</small><strong>${escape(value)}</strong></div>`;
 function evidenceHref(){return 'index.html?scope='+encodeURIComponent(scope)+'&cause='+encodeURIComponent(chosen().root_cause)+'#harm'}
 function render(){
  $('#integration-steps').innerHTML=names.map((n,i)=>`<button data-step="${i}" ${i>3&&!result?'disabled':''} ${i===step?'aria-current="step"':''} class="${result&&i<5?'done':''}"><span>0${i+1}</span>${n}</button>`).join('');
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render()});
  $('#step-progress').textContent=`Step ${step+1} of 6`;
  $('#integration-back').disabled=step===0;
  $('#integration-next').disabled=step===5||(step===3&&!result);
  $('#integration-next').textContent=step===5?'Walkthrough complete':'Next step →';
  const s=source(),c=chosen(),r=result;
  const title=(eyebrow,heading,copy)=>`<div class="eyebrow">${eyebrow}</div><h3>${heading}</h3><p>${copy}</p>`;
  let html='';
  if(step===0){
   html=title('01 / SOURCE CASE SYSTEM','Start where the operational work happens.','A fictional case record based on this programme’s synthetic extract. The source labels below are illustrative, not documented Respond field names. No customer names, account details or complaint narratives are needed for this analytical view.');
   html+=`<div class="pick-case"><label for="source-case">Follow a synthetic case</label><select id="source-case">${pool.map((x,i)=>`<option value="${i}" ${i===selected?'selected':''}>${x.case_id} · ${x.product} · ${x.complaint_type}</option>`).join('')}</select></div><div class="content-grid"><div class="source-card"><div class="source-heading"><strong>Illustrative source record</strong><span>CONCEPT SCREEN · NOT APTEAN UI</span></div><div class="source-fields">${field('Case reference',s.CaseReference)}${field('Workflow stage',s.WorkflowStage)}${field('Product / context',s.ProductCategory)}${field('Complaint type',s.ComplaintCategory)}${field('Pathway',s.ComplaintPathway)}${field('Evidence status',s.EvidenceCompleteness)}${field('Specialist review',s.SpecialistReview)}${field('Reported safety concern',s.ReportedSafetyConcern)}${field('Received date',s.DateReceived)}${field('Root-cause theme',s.RootCauseTheme)}${field('Additional support required',s.SupportRequired)}${field('Decision',s.Decision)}${field('Recorded award GBP',gbp(s.RecordedAwardGBP))}${field('Review team',s.ReviewTeam)}${field('QA result',s.QualityResult)}</div><div class="context-evidence" id="case-context-evidence"></div></div><aside class="control-card"><h4>What remains in the case platform?</h4><p>Evidence, investigation notes, workflow decisions, approval history and customer communications remain under the source system’s governance.</p><h4>What the analytical connection needs</h4><ul><li>A stable case reference for lineage</li><li>Agreed product, stage and cause definitions</li><li>Minimised support indicators</li><li>Clear distinctions between awards and payments</li></ul></aside></div>`;
  }else if(step===1){
   html=title('02 / GOVERNED CONNECTION','Choose a proposed transfer pattern.','Both options below use the same local synthetic fixture. Selecting API mode changes the design explanation only; it does not make a network request or claim a supported Respond endpoint.');
   html+=`<div class="transfer-options"><label><input type="radio" name="transfer" value="extract" ${mode==='extract'?'checked':''}><span><b>Governed extract</b><small>Start with an approved scheduled CSV or file export, subject to what the firm’s Respond installation supports. Validate and reconcile each delivery before loading.</small></span></label><label><input type="radio" name="transfer" value="api" ${mode==='api'?'checked':''}><span><b>Supported API adapter — design stub</b><small>A future server-side adapter would use an interface agreed with Aptean and the platform owner. Authentication, permissions, filters and checkpoints are deployment-specific.</small></span></label></div><div class="content-grid"><div><pre>${escape(JSON.stringify({demo_only:true,source_system:'Aptean Respond — conceptual upstream system',transfer:mode==='extract'?'governed_file_extract':'supported_api_adapter_design_only',batch_reference:'DEMO-RESPOND-001',schema_version:'fictional-contract-v1',snapshot:data.as_of,records_in_fixture:batch().length,selected_context:scope,network_request_performed:false},null,2))}</pre></div><aside class="control-card"><h4>${mode==='extract'?'File delivery controls to agree':'API controls to agree'}</h4><p>${mode==='extract'?'Approved export permissions, encrypted delivery, manifest, file completeness, row reconciliation, retention and controlled reprocessing.':'Approved service identity, least-privilege access, secrets held server-side, supported interface/version, checkpointing, bounded retries, completeness reconciliation and monitoring.'}</p><p>None of these production infrastructure controls is provisioned by this static demo.</p></aside></div>`;
  }else if(step===2){
   const canonical=RespondDemo.canonical(s);
   html=title('03 / AGREED DATA CONTRACT','Make the translation explicit.','The same source case is transformed by a working local adapter. A BA would agree definitions and mappings with operations, data owners and the Respond configuration team before implementation.');
   html+=`<div class="table-scroll"><table class="mapping-table"><thead><tr><th>Illustrative source field / value</th><th>Analytical field / value</th><th>Mapping & control intent</th></tr></thead><tbody>${RespondDemo.mappings.map(([from,to,note])=>`<tr><td>${from}<small>${escape(Array.isArray(s[from])?s[from].join(', '):s[from])}</small></td><td><b>${to}</b><small>${escape(canonical[to])}</small></td><td>${note}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Exact mappings are illustrative. A real Respond schema and the firm’s configured reference values must be confirmed, not inferred from this mock record.</p>`;
  }else if(step===3){
   html=title('04 / VALIDATION & EXCEPTION HANDLING','Stop bad data before it becomes MI.','Run a 12-record synthetic batch from the selected context. With exception testing enabled, the fixture adds three rows: a duplicate reference, a missing reference and a negative award. Rejected rows are quarantined from this demo’s accepted batch.');
   html+=`<div class="batch-actions"><label><input id="include-exceptions" type="checkbox" ${includeExceptions?'checked':''}> Include deliberate data-quality exceptions</label><button id="run-validation">${r?'Re-run':'Run'} validation →</button></div>`;
   if(r){html+=`<div class="batch-totals"><div><strong>${r.input}</strong><span>rows received</span></div><div><strong>${r.totals.accepted}</strong><span>accepted rows</span></div><div><strong>${r.totals.rejected}</strong><span>rejected rows</span></div><div><strong>${r.reconciled?'PASS':'FAIL'}</strong><span>input = accepted + rejected</span></div></div><div class="batch-result">Validation run ${runCount}: ${r.reconciled?'row totals reconcile.':'reconciliation failed.'} ${r.rejected.length?'Rejected rows require correction at source and controlled reprocessing. They are excluded from the batch MI.':'No rejected rows in this fixture.'}</div>`;
    if(r.rejected.length)html+=`<h4 class="exception-title">Exception queue · local demo only</h4><div class="table-scroll"><table class="exception-table"><thead><tr><th>Source row</th><th>Reference</th><th>Reasons for rejection</th></tr></thead><tbody>${r.rejected.map(x=>`<tr><td>${x.row}</td><td>${escape(x.reference)}</td><td>${x.errors.map(escape).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`;
   }else html+='<div class="control-card"><h4>Checks performed by the demo</h4><p>Required and unique case reference; valid snapshot-bounded date; agreed product, cause, stage, team and cohort values; explicit support flag; award value and decision consistency; QA enumeration; linked theme integrity.</p></div>';
   html+='<p class="footnote">Duplicate detection is within this batch only. This static demonstration does not provide a persistent quarantine, cross-batch deduplication, replay protection or source corrections.</p>';
  }else if(step===4){
   const cause=data.causes.find(x=>x.name===c.root_cause);
   html=title('05 / CALCULATED MI & LINEAGE','Accepted data becomes explainable insight.','These batch figures are calculated from accepted rows by the local adapter. The command centre uses reproducible Python/SQLite aggregates for the selected context within its 10,000-case snapshot; running this demo never adds or overwrites its cases.');
   html+=`<div class="batch-totals"><div><strong>${r.totals.accepted}</strong><span>accepted batch cases</span></div><div><strong>${gbp(r.totals.redress)}</strong><span>batch recorded awards</span></div><div><strong>${pct(r.totals.failed,r.totals.sampled)}</strong><span>batch QA failure</span></div><div><strong>${r.totals.failed} / ${r.totals.sampled}</strong><span>failed / sampled QA</span></div></div><div class="content-grid"><div class="lineage"><div><small>STABLE SOURCE REFERENCE</small><b>${c.case_id}</b></div><div><small>CANONICAL PRIMARY CAUSE</small><b>${escape(c.root_cause)}</b></div><div><small>SELECTED-CONTEXT PYTHON / SQLITE AGGREGATE</small><b>${cause.volume.toLocaleString('en-GB')} cases · ${gbp(cause.redress)} recorded awards</b></div><div><small>COMMAND CENTRE DESTINATION</small><b>Customer Harm → ${escape(c.root_cause)}</b></div><a class="evidence-link" href="${evidenceHref()}">Open this cause in the 3D network ↗</a></div><aside class="control-card"><h4>Keep the evidence chain visible.</h4><p>Source case reference → agreed field mapping → validation result → accepted dataset → aggregate cause → operational review. The selected source record comes from the same synthetic dataset as the full programme.</p><p>Batch QA uses failed / sampled rows only. Co-occurrence is association, not proof of causation. Award value does not mean paid redress.</p></aside></div>`;
  }else{
   html=title('06 / INSIGHT → HUMAN REVIEW → SOURCE-SYSTEM FOLLOW-UP','Close the loop without surrendering control.','A proposed operational review is prepared from the accepted batch. A named person would challenge the data, approve any action and record the outcome under the firm’s case-management controls.');
   html+=`<div class="content-grid"><div><div class="source-card"><div class="eyebrow">RULE-BASED PROPOSED REVIEW · NOT A CUSTOMER DECISION</div><h3>Review data quality and QA exceptions.</h3><p class="footnote">The latest demo run accepted ${r.totals.accepted} of ${r.input} rows and held ${r.totals.rejected} for correction. Accepted sampled QA contains ${r.totals.failed} failures from ${r.totals.sampled} sampled cases (${pct(r.totals.failed,r.totals.sampled)}). Inspect source evidence before approving a process or capacity change.</p><p class="footnote">Suggested owner: programme MI / QA lead (fictional role). Follow-up reference: ${c.case_id}. No person is assigned and no source record is changed.</p></div><label class="review-ack"><input id="respond-ack" type="checkbox" ${ack?'checked':''}><span>I have reviewed the mapping, exceptions and proposed follow-up.<small>Local acknowledgement only. Not an approval of a case, payment or production integration.</small></span></label><p id="respond-review-status" class="footnote">${ack?'Acknowledged in this browser session. Formal approval and source-system recording remain outside the demo.':'Awaiting local reviewer acknowledgement.'}</p><button id="download-receipt" class="primary-small">Download integration evidence pack ↓</button></div><aside class="control-card"><h4>What would return to Respond?</h4><p>Subject to the firm’s agreed operating model, an authorised person could record an investigation task, approved action or review reference in Respond. A technical write-back would require a separately approved, supported interface, permissions and audit design.</p><h4>What this prototype actually does</h4><p>Creates a downloadable local evidence pack. It does not call Respond, create a task, change a customer outcome, approve an award or send a communication.</p></aside></div>`;
  }
  $('#integration-content').innerHTML=html;
  if(step===0){
   $('#source-case').onchange=e=>{selected=Number(e.target.value);ack=false;render()};
   const p=fullData.programmes.find(p=>p.product===c.product);
   $('#case-context-evidence').innerHTML=`<b>Evidence to investigate this context</b><ul>${p.evidence.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><p>${escape(p.control)}</p>`;
  }
  if(step===1)document.querySelectorAll('[name=transfer]').forEach(input=>input.onchange=e=>{mode=e.target.value;ack=false;render()});
  if(step===3){$('#include-exceptions').onchange=e=>{includeExceptions=e.target.checked;result=null;ack=false;render()};$('#run-validation').onclick=()=>{result=RespondDemo.validateBatch(batch(),data.as_of,fullData.programmes);runCount++;ack=false;render()}};
  if(step===5){$('#respond-ack').onchange=e=>{ack=e.target.checked;$('#respond-review-status').textContent=ack?'Acknowledged in this browser session. Formal approval and source-system recording remain outside the demo.':'Awaiting local reviewer acknowledgement.'};$('#download-receipt').onclick=downloadReceipt}
 }
 function downloadReceipt(){
  const pack={title:'Simulated Aptean Respond integration evidence',demo_only:true,not_vendor_api_specification:true,prepared_at:new Date().toISOString(),snapshot:data.as_of,source_reference:chosen().case_id,transfer_design:mode,selected_context:scope,network_request_to_respond:false,fictional_source_record:source(),canonical_record:RespondDemo.canonical(source()),field_mapping:RespondDemo.mappings,batch:{input:result.input,...result.totals,reconciled:result.reconciled,rejected_records:result.rejected},local_reviewer_acknowledged:ack,source_system_write_back:false,limits:['No live Respond connection','No persistent audit or quarantine','In-batch deduplication only','No customer outcome or payment approval','Full programme snapshot is unchanged']};
  const url=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='respond-integration-evidence-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
 $('#integration-back').onclick=()=>{if(step>0){step--;render()}};
 $('#integration-next').onclick=()=>{if(step<5&&(step!==3||result)){step++;render()}};
 function selectContext(key){
  scope=key;const subset=fullData.cases.filter(c=>ProgrammeExplorer.matches(c,key));
  data=key==='all'?fullData:fullData.views[key];
  // Start with one example per complaint type in this context, then fill to 12 unique cases.
  let representatives=[];const seenTypes=new Set();
  if(key==='all'){
   fullData.programmes.forEach(p=>{const examples=subset.filter(c=>c.product===p.product);representatives.push(examples[0]);if(p.product==='Motor Finance')representatives.push(examples.find(c=>c.pathway!==examples[0].pathway));else representatives.push(examples.find(c=>c.complaint_type!==examples[0].complaint_type)||examples[1])});
  }else subset.forEach(c=>{if(!seenTypes.has(c.complaint_type)){representatives.push(c);seenTypes.add(c.complaint_type)}});
  const seen=new Set();pool=[...representatives,...subset].filter(c=>c&&!seen.has(c.case_id)&&seen.add(c.case_id)).slice(0,12);
  selected=0;step=0;result=null;ack=false;runCount=0;
  const profile=ProgrammeExplorer.profile(fullData,key);
  $('#respond-context-description').textContent=(profile?profile.summary+' '+profile.control:'Select pensions, investments, savings, mortgages, collections & recoveries or either motor-finance pathway. Each context has relevant source cases, evidence and control points.')+' Changing context resets the batch and review acknowledgement.';
  $('#integration-status').textContent='Ready · '+(key==='all'?'all six areas':key.replace('::',' · '))+' · 12 synthetic cases · no Respond request';
  const url=new URL(window.location.href);if(key==='all')url.searchParams.delete('scope');else url.searchParams.set('scope',key);window.history.replaceState({},'',url);
  render();
 }
 fetch('analytics.json?v=six-areas-1').then(r=>{if(!r.ok)throw Error('Synthetic extract unavailable');return r.json()}).then(d=>{fullData=d;const requested=new URLSearchParams(window.location.search).get('scope')||'all';const initial=requested==='all'||d.views[requested]?requested:'all';const picker=$('#respond-context');picker.innerHTML=ProgrammeExplorer.options(d.programmes,initial);picker.value=initial;picker.disabled=false;picker.onchange=()=>selectContext(picker.value);selectContext(initial)}).catch(()=>{$('#integration-status').textContent='The synthetic extract could not load. Reload this page when the site is available.';$('#integration-next').disabled=true});
})();

